    public var to: String
    public var activities: [Activity]
    public var locations: [Location]?
    public var plans: [Plan]
    public var sessions: [PlannedSession]
    public var efforts: [PerformedEffort]

    public init(from: String, to: String, activities: [Activity], locations: [Location]? = nil, plans: [Plan], sessions: [PlannedSession], efforts: [PerformedEffort]) {
        self.from = from
        self.to = to
        self.activities = activities
        self.locations = locations
        self.plans = plans
        self.sessions = sessions
        self.efforts = efforts
    }

    enum CodingKeys: String, CodingKey {
        case from
        case to
        case activities
        case locations
        case plans
        case sessions
        case efforts
    }
}

/// POST /v0/events. Events authored on the app, oldest first. Each must carry the paired device's id and the actor human/me; a different device or actor is rejected.
public struct EventsRequest: Codable, Equatable, Hashable, Sendable {
    public var events: [Event]

    public init(events: [Event]) {
        self.events = events
    }

    enum CodingKeys: String, CodingKey {
        case events
    }
}

public struct EventResult: Codable, Equatable, Hashable, Sendable {
    public var index: Int
    public var id: String?
    /// `accepted` and `duplicate` both mean the server has it, so the app can forget it. `rejected` will not change on retry.
    public var status: EventStatus
    public var errors: [JSONValue]?

    public init(index: Int, id: String? = nil, status: EventStatus, errors: [JSONValue]? = nil) {
        self.index = index
        self.id = id
        self.status = status
        self.errors = errors
    }

    enum CodingKeys: String, CodingKey {
        case index
        case id
        case status
        case errors
    }
}

public struct EventsResponse: Codable, Equatable, Hashable, Sendable {
    public var results: [EventResult]
    public var accepted: Int
    public var duplicate: Int
    public var rejected: Int

    public init(results: [EventResult], accepted: Int, duplicate: Int, rejected: Int) {
        self.results = results
        self.accepted = accepted
        self.duplicate = duplicate
        self.rejected = rejected
    }

    enum CodingKeys: String, CodingKey {
        case results
        case accepted
        case duplicate
        case rejected
    }
}

/// POST /v0/telemetry. Samples read on the phone, such as body mass from HealthKit. Sending a sample again changes nothing.
public struct TelemetryRequest: Codable, Equatable, Hashable, Sendable {
    public var samples: [TelemetrySample]

    public init(samples: [TelemetrySample]) {
        self.samples = samples
    }

    enum CodingKeys: String, CodingKey {
        case samples
    }
}

public struct TelemetryResponse: Codable, Equatable, Hashable, Sendable {
    public var inserted: Int
    public var updated: Int
    public var unchanged: Int
    public var rejected: [JSONValue]

    public init(inserted: Int, updated: Int, unchanged: Int, rejected: [JSONValue]) {
        self.inserted = inserted
        self.updated = updated
        self.unchanged = unchanged
        self.rejected = rejected
    }

    enum CodingKeys: String, CodingKey {
        case inserted
        case updated
        case unchanged
        case rejected
    }
}

/// The registry metrics from the contract: what each measures, its units and bounds.
/// Anything else must be a custom metric named `x.something`.
public enum MetricRegistry {
    public static let customNamePattern = "^x\\.[a-z0-9][a-z0-9_.-]{0,62}$"

    public static let all: [MetricSpec] = [
        MetricSpec(name: "reps", summary: "Repetitions.", units: [], unitRequired: false, kind: .integer, minimum: 0.0, maximum: nil, pattern: nil),
        MetricSpec(name: "load", summary: "Weight moved, or a share of your one-rep max.", units: ["kg", "lb", "%1rm"], unitRequired: true, kind: .number, minimum: 0.0, maximum: nil, pattern: nil),
        MetricSpec(name: "duration", summary: "How long. On a block, how long each round lasts (an EMOM is 60 s).", units: ["s", "min", "h"], unitRequired: true, kind: .number, minimum: 0.0, maximum: nil, pattern: nil),
        MetricSpec(name: "distance", summary: "How far.", units: ["m", "km", "mi", "yd", "ft"], unitRequired: true, kind: .number, minimum: 0.0, maximum: nil, pattern: nil),
        MetricSpec(name: "pace", summary: "Time per distance.", units: ["s/km", "s/mi", "s/100m", "s/500m"], unitRequired: true, kind: .number, minimum: 0.0, maximum: nil, pattern: nil),
        MetricSpec(name: "heart_rate", summary: "Heart rate.", units: ["bpm"], unitRequired: true, kind: .number, minimum: 0.0, maximum: 300.0, pattern: nil),
        MetricSpec(name: "power", summary: "Power output.", units: ["W"], unitRequired: true, kind: .number, minimum: 0.0, maximum: nil, pattern: nil),
        MetricSpec(name: "rpe", summary: "Rate of perceived exertion, 0 to 10.", units: [], unitRequired: false, kind: .number, minimum: 0.0, maximum: 10.0, pattern: nil),
        MetricSpec(name: "rir", summary: "Reps in reserve.", units: [], unitRequired: false, kind: .number, minimum: 0.0, maximum: nil, pattern: nil),
        MetricSpec(name: "rest", summary: "Rest after this effort (or, on a block, between rounds).", units: ["s", "min"], unitRequired: true, kind: .number, minimum: 0.0, maximum: nil, pattern: nil),
        MetricSpec(name: "tempo", summary: "Lifting tempo: eccentric, bottom, concentric, top, e.g. 3010.", units: [], unitRequired: false, kind: .text, minimum: nil, maximum: nil, pattern: "^[0-9xX]{4}$"),
        MetricSpec(name: "incline", summary: "Treadmill or ramp incline; negative is a decline.", units: ["%", "deg"], unitRequired: true, kind: .number, minimum: nil, maximum: nil, pattern: nil),
    ]
}
